package io.github.rebrowser.data;
import static org.junit.Assert.*;
import java.nio.*;
import java.util.*;
import org.junit.Test;
public class NativeRecordCodecTest {
 @Test public void primitivesCanonicalRoundTrip(){byte[] b=new NativeRecordCodec.Writer("TEST0001",128).u8(255).u16(65535).nonnegative(Long.MAX_VALUE).bool(true).text("书😀",7,false).finish();NativeRecordCodec.Reader r=new NativeRecordCodec.Reader(ByteBuffer.wrap(b),"TEST0001",128);assertEquals(255,r.u8());assertEquals(65535,r.u16());assertEquals(Long.MAX_VALUE,r.nonnegative());assertTrue(r.bool());assertEquals("书😀",r.text(7,false));r.end();}
 @Test public void writerBoundsBeforeExpansion(){NativeRecordCodec.Writer w=new NativeRecordCodec.Writer("TEST0001",16);assertThrows(IllegalArgumentException.class,()->w.nonnegative(0));assertThrows(IllegalArgumentException.class,()->new NativeRecordCodec.Writer("TEST0001",16).text("12345",5,false));}
 @Test public void strictUtf16AndActualUtf8Budget(){for(String s:Arrays.asList("\ud800","\udc00","a\n","a\u0000"))assertThrows(IllegalArgumentException.class,()->NativeRecordCodec.validateText(s,32,true));assertThrows(IllegalArgumentException.class,()->NativeRecordCodec.validateText("😀",3,false));assertEquals("😀",NativeRecordCodec.validateText("😀",4,false));}
 @Test public void invalidIntegerAndBooleanAreNotCoerced(){assertThrows(IllegalArgumentException.class,()->new NativeRecordCodec.Writer("TEST0001",32).u8(256));assertThrows(IllegalArgumentException.class,()->new NativeRecordCodec.Writer("TEST0001",32).nonnegative(-1));byte[] b=new NativeRecordCodec.Writer("TEST0001",32).u8(2).finish();assertThrows(IllegalArgumentException.class,()->new NativeRecordCodec.Reader(ByteBuffer.wrap(b),"TEST0001",32).bool());}
 @Test public void exactEofAndMagicAndVersion(){byte[] b=new NativeRecordCodec.Writer("TEST0001",32).u8(1).finish();assertThrows(IllegalArgumentException.class,()->new NativeRecordCodec.Reader(ByteBuffer.wrap(b),"TEST0001",32).end());assertThrows(IllegalArgumentException.class,()->new NativeRecordCodec.Reader(ByteBuffer.wrap(b),"TEST0002",32));b[9]=2;assertThrows(IllegalArgumentException.class,()->new NativeRecordCodec.Reader(ByteBuffer.wrap(b),"TEST0001",32));}
 @Test public void truncatedAndOversizeStringRejectedBeforeDecode(){byte[] b=new NativeRecordCodec.Writer("TEST0001",32).u16(65535).finish();assertThrows(IllegalArgumentException.class,()->new NativeRecordCodec.Reader(ByteBuffer.wrap(b),"TEST0001",32).text(8,true));}
 @Test public void malformedUtf8NeverReplacementDecoded(){byte[] b=new NativeRecordCodec.Writer("TEST0001",32).u16(2).u8(0xc0).u8(0x80).finish();assertThrows(IllegalArgumentException.class,()->new NativeRecordCodec.Reader(ByteBuffer.wrap(b),"TEST0001",32).text(8,true));}
 @Test public void borrowedInputPositionAndByteOrderUnchanged(){byte[] b=new NativeRecordCodec.Writer("TEST0001",32).nonnegative(257).finish();ByteBuffer input=ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN);NativeRecordCodec.Reader r=new NativeRecordCodec.Reader(input,"TEST0001",32);assertEquals(257,r.nonnegative());assertEquals(0,input.position());assertEquals(ByteOrder.LITTLE_ENDIAN,input.order());}
 @Test public void negativeReadAndBadMagicReject(){byte[] b=new NativeRecordCodec.Writer("TEST0001",32).u8(128).u8(0).u16(0).u16(0).u16(0).finish();assertThrows(IllegalArgumentException.class,()->new NativeRecordCodec.Reader(ByteBuffer.wrap(b),"TEST0001",32).nonnegative());assertThrows(IllegalArgumentException.class,()->new NativeRecordCodec.Writer("short",32));}
 @Test public void everyTruncationRejectsWithoutMutatingInput(){byte[] good=new NativeRecordCodec.Writer("TEST0001",128).text("test😀",32,false).nonnegative(1).finish();for(int n=0;n<good.length;n++){byte[] cut=Arrays.copyOf(good,n);assertThrows(IllegalArgumentException.class,()->{NativeRecordCodec.Reader r=new NativeRecordCodec.Reader(ByteBuffer.wrap(cut),"TEST0001",128);r.text(32,false);r.nonnegative();r.end();});}}
}
